#!/usr/bin/env node
'use strict';
// Sources remain individually editable. Preserve classic-script registration order.
const fs=require('node:fs'),path=require('node:path');
const root=path.resolve(__dirname,'..');
function generated(){
 const loader=fs.readFileSync(path.join(root,'js/players-loader.js'),'utf8');
 const folders=JSON.parse(/const folders = (\[[^\]]*\]);/.exec(loader)[1]);
 return '// Generated by node scripts/bundle-characters.js. Edit js/players/* sources.\n'+
 ['player.js','reference.js'].flatMap(name=>folders.map(folder=>{
  const file=`js/players/${folder}/${name}`;
  return `\n// ${file}\n`+fs.readFileSync(path.join(root,file),'utf8').replace(/\r\n/g,'\n').trimEnd()+'\n;\n';
 })).join('');
}
function check(){return fs.readFileSync(path.join(root,'js/characters.generated.js'),'utf8')===generated();}
if(require.main===module){if(process.argv.includes('--check')){if(!check())throw Error('Stale character bundle: node scripts/bundle-characters.js');console.log('PASS deterministic character bundle');}else fs.writeFileSync(path.join(root,'js/characters.generated.js'),generated());}
module.exports={generated,check};
